// RB1-7: exercise the actual hit and telegraph paths, not just table constants.
using System;using System.Linq;using System.Collections.Generic;using Exoduser.UnityPort.Core;
static partial class P {
static Simulation ReachFight(){var s=new Simulation(new SimulationConfig{StageIndex=0,DifficultyIndex=5,EnemyAiEnabled=true,PlayerMaxHp=2000000,PlayerBaseAttack=40},20261027u);s.DruidRemodel=true;s.Player.Level=8;s.AttachDruidBoss();s.Stage.Enabled=true;s.Stage.FieldBossDone=true;s.Stage.BossUnlocked=true;s.Stage.Exits.Add(new StageFlow.Tile(100,7));s.Player.X=4020;s.Player.Y=300;s.Stage.CheckT=29;int guard=0;while(guard++<1500&&!(s.Stage.InArena&&s.Stage.LoadPhase==0&&s.Stage.Boss!=null))s.Tick(0,0,4200,300,false,false);for(int i=0;i<200;i++)s.Tick(0,0,s.Stage.Boss.X,s.Stage.Boss.Y,false,false);return s;}
static void PlaceMove(Simulation s,string state,double ticks,string id){var e=s.Stage.Boss;var d=s.Druid.Data[e];e.X=2560;e.Y=2160;d.X=e.X;d.Y=e.Y;e.State=d.S=state;e.StateTicks=(float)(d.St2=ticks);e.Facing=0;d.Facing=0;d.RmDir=0;d.EchDx=1;d.EchDy=0;d.RmMoveId=id;d.SlashIdx=0;d.SlashCnt=3;d.RmTeleTotal=58;d.RmVel=0;e.Stunned=0;e.HitStun=0;e.ReviveIframes=0;e.KnockbackX=e.KnockbackY=0;s.Player.Iframes=0;s.Player.Hp=s.Player.MaxHp;}
static void ReachChecks(){var s=ReachFight();var e=s.Stage.Boss;var d=s.Druid.Data[e];var list=new List<DruidTelegraph>();
foreach(bool inside in new[]{true,false}){PlaceMove(s,"bossSlash",7,"slashCombo");s.Player.X=e.X+2.5f+e.Radius+s.Player.Radius+(inside?479:481);s.Player.Y=e.Y;float hp=s.Player.Hp;s.Druid.TickBoss(e);Check((s.Player.Hp<hp)==inside,"RB1-7 actual slash boundary 480 inside="+inside);}
PlaceMove(s,"bossSlashWind",36,"slashCombo");d.RmTeleTotal=36;s.DruidTelegraphs(list);Check(list.Any(t=>t.MoveId=="slashCombo"&&Math.Abs(t.Radius-(e.Radius+s.Player.Radius+480))<1e-6),"RB1-7 slash telegraph follows actual reach");
foreach(bool inside in new[]{true,false}){PlaceMove(s,"bossCharge",40,"charge");double r=(e.Radius+s.Player.Radius+80)*1.5;s.Player.X=e.X+22;s.Player.Y=(float)(e.Y+r+(inside?-1:1));float hp=s.Player.Hp;s.Druid.TickBoss(e);Check((s.Player.Hp<hp)==inside,"RB1-7 actual charge width inside="+inside);}
PlaceMove(s,"bossChargeWind",58,"charge");s.DruidTelegraphs(list);Check(list.Any(t=>t.MoveId=="charge"&&Math.Abs(t.Width-2*(e.Radius+s.Player.Radius+80)*1.5)<1e-6),"RB1-7 charge telegraph matches scaled judgement");
PlaceMove(s,"bossDruidUnder",1,"burrowStrike");d.UnderMax=45;d.TeleOx=d.X;d.TeleOy=d.Y;d.DiveTx=3240;d.DiveTy=3040;s.Druid.TickBoss(e);double ring=s.Druid.Pillars.Min(pi=>Math.Abs(Dist(d.X,d.Y,pi.X,pi.Y)-(pi.R+d.R+24)));Check(ring<.001,"burrow arrival uses pillar radius + body +24");s.HurtEnemy(e,100,0);Check(e.KnockbackX>0,"burrow regression probe receives real hit knockback");for(int i=0;i<12;i++)s.Druid.TickBoss(e);ring=s.Druid.Pillars.Min(pi=>Math.Abs(Dist(d.X,d.Y,pi.X,pi.Y)-(pi.R+d.R+24)));Check(ring>3,"burrow after-hit position may leave initial 3px ring");s.DruidTelegraphs(list);Check(list.Any(t=>t.MoveId=="burrowStrike"&&Math.Abs(t.X-d.X)<.001&&Math.Abs(t.Y-d.Y)<.001),"burrow erupt telegraph follows actual knocked-back boss");}
}
